// v: {items:{id:val}, mat:cost, cont:pct, fuel, miles, dump:key, tons, dump2:key,tons2, grt:key}
function calc(fk,v){var f=FORMS[fk],L=[],warn=[];var it=v.items||{};
 f.items.forEach(function(d){var x=it[d.id];var a=0,lbl=d.l;
  if(!d.type){var q=+x||0;if(!q)return;a=q*d.rate;if(d.min&&a<d.min){a=d.min;warn.push(d.minNote);}lbl=d.l.replace(/ - .*/,"")+" ("+q+" "+d.u+" x $"+d.rate+")";}
  else if(d.type=="range"){if(!x||x.k=="none")return;var o=d.opts[x.k];a=+x.p||0;if(a<o[1]){warn.push(o[0]+": raised to $"+o[1]+" floor");a=o[1];}if(a>o[2])warn.push(o[0]+": price above range - owner OK needed");lbl="Yard cleanup - "+o[0].split(" (")[0];}
  else if(d.type=="monthly"){if(!x||!x.n)return;var p=+x.p||0;if(p<d.minp){warn.push("Monthly care raised to $85 minimum");p=d.minp;}a=p*x.n;lbl="Monthly yard care ("+x.n+" mo x $"+p+")";}
  else if(d.type=="dirt"){var q=+x||0;if(!q)return;a=200+Math.max(0,Math.ceil(q)-2)*100;lbl="Dirt haul ("+q+" cu yd: $200 first 2 + $100/yd after)";}
  else if(d.type=="pick"){if(!x||x=="none")return;a=d.opts[x][1];lbl="Junk removal - "+d.opts[x][0];}
  else if(d.type=="per"){if(!x||!x.n)return;var p=+x.p||0;if(p<d.lo){warn.push(d.l+": price raised to $"+d.lo);p=d.lo;}if(p>d.hi){warn.push(d.l+": capped at $"+d.hi);p=d.hi;}a=x.n*p;lbl="Tree "+d.l.split(" (")[0].toLowerCase()+" ("+x.n+" x $"+p+")";}
  else if(d.type=="floor"){if(!x)return;a=+x;if(a<d.floor){warn.push("Raised to $"+d.floor+" floor");a=d.floor;}lbl="Green pool cleanup";}
  else if(d.type=="gutter"){if(!x||!x.s)return;var ft=+x.ft||0;if(x.s==1){a=140;lbl="Gutter cleaning - one story (flat)";if(ft>175){a=140+(ft-175)*0.85;lbl="Gutter cleaning - one story ($140 up to 175 ft + "+r2(ft-175)+" ft x $0.85)";}}else{a=250+Math.max(0,ft-175)*1.40;lbl="Gutter cleaning - two story ($250 up to 175 ft"+(ft>175?" + "+r2(ft-175)+" ft x $1.40":"")+")";}}
  else if(d.type=="custom"){(x||[]).forEach(function(c){var s=(+c.q||0)*(+c.p||0);if(s)L.push({l:c.d+" ("+c.q+" x $"+c.p+")",a:r2(s),k:"svc"});});return;}
  if(d.pending)lbl+=" [PENDING]";L.push({l:lbl,a:r2(a),k:"svc"});});
 var svc=L.reduce(function(s,i){return s+i.a},0);
 var mc=+v.mat||0,mat=0;if(mc){mat=r2(mc*1.2*1.1);L.push({l:"Materials (cost $"+mc.toFixed(2)+" + 20% markup + 10% waste)",a:mat,k:"mat"});}
 var base=svc+mat,cp=+v.cont||0,cont=0;if(cp){if(cp<5||cp>10)warn.push("Contingency should be 5-10%");cont=r2(base*cp/100);L.push({l:"Contingency "+cp+"% (site not seen in person)",a:cont,k:"c"});}
 var fu=+v.fuel||0;if(fu){if(fu<15||fu>25)warn.push("Fuel should be $15-25");L.push({l:"Fuel / trip charge",a:r2(fu),k:"f"});}
 var mi=+v.miles||0;if(mi){L.push({l:"Mileage outside service area ("+mi+" mi x $0.76)",a:r2(mi*0.76),k:"f"});}
 [["dump","tons"],["dump2","tons2"]].forEach(function(p){var d=DUMP[v[p[0]]];if(!d||(!d.flat&&!d.per))return;var t=+v[p[1]]||0;var a=d.flat?d.flat:t*d.per;if(a)L.push({l:"Dump fee - "+d.l.replace(/ \(.*/,"")+(d.flat?"":" ("+t+" ton)"),a:r2(a),k:"d"});});
 var sub=r2(L.reduce(function(s,i){return s+i.a},0));var g=GRT[v.grt]||GRT.rrs;var tax=r2(sub*g.r/100);
 return {lines:L,subtotal:sub,grtLabel:g.l,grtRate:g.r,tax:tax,total:r2(sub+tax),warn:warn};}
var api={calc:calc,FORMS:FORMS,GRT:GRT,DUMP:DUMP,OWNER_NOTE:OWNER_NOTE};
